  private static final Map<String, Country> BY_ALPHA_2;

  private static final Map<String, Country> BY_ALPHA_3;

  private static final Map<String, Country> BY_NUMERIC;

  static {
    Map<String, Country> by_alpha_2 = new HashMap<>();
    Map<String, Country> by_alpha_3 = new HashMap<>();
    Map<String, Country> by_numeric = new HashMap<>();
    for (Country entry : values()) {
      by_alpha_2.put(entry.alpha2, entry);
      by_alpha_3.put(entry.alpha3, entry);
      by_numeric.put(entry.numeric, entry);
    }
    BY_ALPHA_2 = Map.copyOf(by_alpha_2);
    BY_ALPHA_3 = Map.copyOf(by_alpha_3);
    BY_NUMERIC = Map.copyOf(by_numeric);
  }

  private final String alpha2;

  private final String alpha3;

  private final String flag;

  private final String englishName;

  private final String numeric;

  private final String officialName;

  private final String commonName;

  Country(String alpha2, String alpha3, String flag, String englishName, String numeric,
      String officialName, String commonName) {
    this.alpha2 = alpha2;
    this.alpha3 = alpha3;
    this.flag = flag;
    this.englishName = englishName;
    this.numeric = numeric;
    this.officialName = officialName;
    this.commonName = commonName;
  }

  /**
   * Two letter alphabetic code of the item.
   *
   * @return the value, never null
   */
  public String alpha2() {
    return alpha2;
  }

  /**
   * Three letter alphabetic code of the item.
   *
   * @return the value, never null
   */
  public String alpha3() {
    return alpha3;
  }

  /**
   * Flag of country, using Unicode regional indicator symbol letters.
   *
   * @return the value, never null
   */
  public String flag() {
    return flag;
  }

  /**
   * Name of the item.
   *
   * @return the value, never null
   */
  public String englishName() {
    return englishName;
  }

  /**
   * Three digit numeric code of the item, including leading zeros.
   *
   * @return the value, never null
   */
  public String numeric() {
    return numeric;
  }

  /**
   * Official name of the item.
   *
   * @return the value, or empty if this entry has none
   */
  public Optional<String> officialName() {
    return Optional.ofNullable(officialName);
  }

  /**
   * Common name of the item.
   *
   * @return the value, or empty if this entry has none
   */
  public Optional<String> commonName() {
    return Optional.ofNullable(commonName);
  }

  /**
   * Finds the entry whose {@code alpha_2} is exactly the given value.
   *
   * @param alpha2 the value to look up (case-sensitive)
   * @return the matching entry, or empty if there is none
   */
  public static Optional<Country> fromAlpha2(String alpha2) {
    return Optional.ofNullable(BY_ALPHA_2.get(alpha2));
  }

  /**
   * Finds the entry whose {@code alpha_3} is exactly the given value.
   *
   * @param alpha3 the value to look up (case-sensitive)
   * @return the matching entry, or empty if there is none
   */
  public static Optional<Country> fromAlpha3(String alpha3) {
    return Optional.ofNullable(BY_ALPHA_3.get(alpha3));
  }

  /**
   * Finds the entry whose {@code numeric} is exactly the given value.
   *
   * @param numeric the value to look up (case-sensitive)
   * @return the matching entry, or empty if there is none
   */
  public static Optional<Country> fromNumeric(String numeric) {
    return Optional.ofNullable(BY_NUMERIC.get(numeric));
  }
